const OP_RATES_KEY=RateRepository.KEY;
function rateRepository(){return RateRepository.create({read:readJSON,write:(k,v)=>writeJSON(k,v),seed:OPERATION_RATE_SEED})}
function operationRates(){return rateRepository().list()}
function ratePickerHTML(o){return `<div class="card"><div class="field"><label for="op-rate-profile">Внутренняя ставка из справочника</label><select id="op-rate-profile" onchange="applyOperationRate()"><option value="">Выберите материал и толщину…</option>${operationRates().filter(r=>r.type===o.type).map(r=>`<option value="${esc(r.id)}" ${o.rateProfile?.id===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="mini-actions"><button type="button" onclick="applyOperationRate()">Применить текущую ставку справочника</button><button type="button" onclick="ratesDialog()">Редактировать справочник</button></div><p class="small" id="op-rate-note">${o.rateProfile?'В расчёте сохранена копия ставки '+esc(o.rateProfile.name)+'. Обновление — кнопкой выше.':'Выбор заполняет ставки, подготовку и минимум. Объёмы задаются для изделия.'} ${['laser','waterjet'].includes(o.type)?'При наличии врезок уточните их стоимость.':''}</p></div>`}
function applyOperationRate(){const r=operationRates().find(r=>r.id===$('op-rate-profile').value);if(!r||r.type!==$('op-type').value)return;const o=OperationRatesCore.apply(operationInput(),r);operationMetadata=Object.fromEntries(['materialCode','thickness','equipment','quality','unit'].map(k=>[k,o[k]]));for(const k of OperationRatesCore.FIELDS)if($('op-'+k))$('op-'+k).value=o[k]??'';for(const k of ['mode','material','source'])$('op-'+k).value=o[k];$('op-rate-profile').snapshot=o.rateProfile;$('op-rate-note').textContent='Применена ставка: '+r.name+' · '+r.source;document.querySelectorAll('#modalBody details').forEach(d=>d.open=false);operationPreview();rememberOperationDraft()}
function ratesDialog(){if($('op-type'))rememberOperationDraft();modal('Внутренние ставки обработки',`<p class="small">Ставки из исходного справочника дополнены вашими изменениями. Редактирование действует для последующего выбора ставки; сохранённые калькуляции и КП сохраняют свои значения. Внешний JSON можно скачать, изменить и загрузить обратно. Изменения файла загружаются явно.</p><div class="mini-actions">${OperationEditorStore.current()?'<button onclick="resumeOperationDraft()">← Вернуться к операции</button>':''}<button onclick="editOperationRate()">＋ Новая ставка</button><button onclick="exportOperationRates()">Скачать файл ставок</button><label class="textbutton">Загрузить JSON<input type="file" accept=".json,application/json" onchange="importOperationRates(event)"></label></div><div class="tablewrap"><table><thead><tr><th>Ставка</th><th>Цена</th><th>Источник</th><th></th></tr></thead><tbody>${operationRates().map(r=>`<tr><td>${esc(r.name)}<span class="source">${esc(OperationsCore.TYPES[r.type].name)}</span></td><td>${money(r.mode==='tariff'?r.rate:r.mode==='machine'?r.hourRate:r.manual)} ${r.mode==='machine'?'₽/ч':r.mode==='manual'?'₽/изд.':r.type==='bending'?'₽/гиб':r.type==='milling'?'₽/мин':'₽/м'}</td><td>${esc(r.source)}<span class="source">${esc(r.date||'Дата не указана')}</span></td><td><button onclick="editOperationRate('${r.id}')">Изменить</button></td></tr>`).join('')}</tbody></table></div>`)}
function editOperationRate(id){const r=operationRates().find(r=>r.id===id)||{id:crypto.randomUUID(),type:'laser',mode:'tariff',name:'',material:'',source:'',date:'',setup:0,minimum:0};const text=(k,label)=>`<div class="field"><label for="rate-${k}">${label}</label><input id="rate-${k}" value="${esc(r[k]??'')}"></div>`,number=(k,label)=>`<div class="field"><label for="rate-${k}">${label}</label><input id="rate-${k}" type="number" min="0" step="any" value="${esc(r[k]??'')}"></div>`;modal('Редактировать внутреннюю ставку',`<form onsubmit="saveOperationRate(event,'${r.id}')">${text('name','Название: материал, толщина, условия')}<div class="grid2"><div class="field"><label for="rate-type">Технология</label><select id="rate-type">${Object.entries(OperationsCore.TYPES).map(([k,v])=>`<option value="${k}" ${r.type===k?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label for="rate-mode">Способ расчёта</label><select id="rate-mode">${[['tariff','Тариф'],['machine','Время оборудования'],['manual','Стоимость изделия']].map(([k,v])=>`<option value="${k}" ${r.mode===k?'selected':''}>${v}</option>`).join('')}</select></div></div>${text('material','Материал / описание')}<div class="grid2">${text('materialCode','Марка / код материала')}${number('thickness','Толщина, мм')}${text('equipment','Оборудование')}${text('quality','Качество обработки')}${text('unit','Единица тарифа (м, гиб, мин)')}</div><p class="small">Заполняйте поля выбранного способа. Тариф: ₽/м реза, ₽/гиб или ₽/мин фрезерования. Пустое поле — неизвестная стоимость. Подготовка и минимум относятся к партии; ноль означает, что они не включены.</p><div class="grid2">${number('rate','Тариф за единицу обработки, ₽')}${number('pierceRate','Врезка / прокол, ₽/шт.')}${number('setup','Подготовка партии, ₽')}${number('minimum','Минимум партии, ₽')}${number('hourRate','Оборудование, ₽/ч')}${number('consumables','Дополнительные расходники, ₽/мин')}${number('manual','Ручная стоимость изделия, ₽')}</div>${text('source','Источник и условия')}${text('date','Дата ставки')}<p id="rate-error" class="warning"></p><div class="mini-actions"><button class="primary" type="submit">Сохранить ставку</button><button type="button" onclick="ratesDialog()">Назад</button></div></form>`)}
function saveOperationRate(e,id){e.preventDefault();try{const r={id};for(const k of ['name','type','mode','material','source','date','materialCode','equipment','quality','unit'])r[k]=$('rate-'+k).value;r.thickness=$('rate-thickness').value===''?null:Number($('rate-thickness').value);for(const k of OperationRatesCore.FIELDS)r[k]=$('rate-'+k).value===''?null:Number($('rate-'+k).value);const [valid]=OperationRatesCore.validate({format:'izdelie-operation-rates',version:1,rates:[r]});if(!rateRepository().save(valid))return;ratesDialog()}catch(e){$('rate-error').textContent=e.message}}
function exportOperationRates(){download('Внутренние ставки обработки.json',JSON.stringify({format:'izdelie-operation-rates',version:1,rates:operationRates()},null,2),'application/json')}
async function importOperationRates(e){try{const f=e.target.files[0];if(!f||f.size>1000000)throw Error('Размер файла должен быть до 1 МБ');const rates=OperationRatesCore.validate(JSON.parse(await f.text()));modal('Проверка файла ставок',`<p>Проверено ставок: ${rates.length}. Совпадающие коды обновят справочник; новые будут добавлены. Калькуляции сохранят прежние ставки.</p><div class="mini-actions"><button id="apply-rate-import" class="primary">Применить файл</button><button onclick="ratesDialog()">Отмена</button></div>`);$('apply-rate-import').onclick=()=>{if(rateRepository().importAll(rates))ratesDialog()}}catch(e){toast('Файл не применён: '+e.message)}}
